-- Branding per organisation (docs/branding-plan.md, step 3).
--   1. organization_branding: one row per organisation, with its display name, accent colour, sign-in tint, logo for
--      light backgrounds, logo for dark backgrounds and square icon. Images are PNG, JPEG or WebP data: URLs (never
--      SVG), resized in the browser and checked again by the Worker; at most 200 KB each.
--   2. Every organisation's existing logo and colour (organizations.logo and .colour, from 0017) are copied in. Those
--      two columns are no longer used and are dropped in a later release, once this code is live.
--   3. Omnicontact's logos move here from the app's public files (omni-logo.png and omni-logo-white.png), which are
--      then deleted: after this, nothing outside Omnicontact's own row refers to them.
-- The public sign-in page reads a row through the owner (before sign-in there is no tenant), and only the name,
-- colours and image addresses. Organisation Administrators change their own row through the app's role.
-- Reverse: migrations/down/0021_branding.down.sql.

CREATE TABLE organization_branding (
  organization_id TEXT PRIMARY KEY DEFAULT NULLIF(current_setting('app.org_id', true), '') REFERENCES organizations (id) ON DELETE CASCADE,
  display_name    TEXT NOT NULL CHECK (length(display_name) BETWEEN 1 AND 80),
  accent          TEXT NOT NULL DEFAULT '#3e5c76' CHECK (accent ~ '^#[0-9a-f]{6}$'),
  signin_tint     TEXT CHECK (signin_tint IS NULL OR signin_tint ~ '^#[0-9a-f]{6}$'),
  logo            TEXT CHECK (logo IS NULL OR (logo ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$' AND length(logo) <= 280000)),
  logo_dark       TEXT CHECK (logo_dark IS NULL OR (logo_dark ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$' AND length(logo_dark) <= 280000)),
  icon            TEXT CHECK (icon IS NULL OR (icon ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$' AND length(icon) <= 280000)),
  version         INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),   -- in each image address (?v=), so caches refresh
  updated_at      TEXT NOT NULL,
  updated_by      TEXT
);
ALTER TABLE organization_branding ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant ON organization_branding TO pulse_app
  USING (organization_id = current_setting('app.org_id', true))
  WITH CHECK (organization_id = current_setting('app.org_id', true));
REVOKE DELETE, TRUNCATE ON organization_branding FROM pulse_app;
GRANT SELECT, INSERT, UPDATE ON organization_branding TO pulse_app;

INSERT INTO organization_branding (organization_id, display_name, accent, logo, updated_at)
SELECT id, left(name, 80), COALESCE(colour, '#3e5c76'), logo, to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
FROM organizations;

-- Omnicontact: its two logos and its indigo, unless its administrators already chose their own.
UPDATE organization_branding b
SET logo = COALESCE(b.logo, 'data:image/png;base64,'),
    logo_dark = 'data:image/png;base64,',
    accent = CASE WHEN o.colour IS NULL THEN '#2c3280' ELSE b.accent END,
    version = b.version + 1
FROM organizations o
WHERE o.id = b.organization_id AND o.code = 'omnicontact';
